export function parseData(text,format='json'){
 text=text.replace(/^\uFEFF/,'');let data;
 if(format==='csv'){
  let rows=[],row=[],v='',q=false;
  for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(q&&text[i+1]==='"'){v+='"';i++;}else if(q||!v)q=!q;else throw Error('CSV引号位置错误');}else if(c===','&&!q){row.push(v);v='';}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&text[i+1]==='\n')i++;row.push(v);if(row.some(x=>x!==''))rows.push(row);row=[];v='';}else v+=c;}
  if(q)throw Error('CSV引号未闭合');if(v||row.length){row.push(v);rows.push(row)}const head=rows.shift();if(!head?.length||head.some(x=>!x)||new Set(head).size!==head.length)throw Error('CSV表头为空或重复');
  data=rows.map((r,i)=>{if(r.length!==head.length)throw Error(`CSV第${i+2}行字段数不匹配`);return Object.fromEntries(head.map((h,j)=>[h,r[j]===''?null:r[j]]))});
 }else if(format==='jsonl'||format==='ndjson')data=text.split(/\r?\n/).filter(x=>x.trim()).map((x,i)=>{try{return JSON.parse(x)}catch{throw Error(`JSONL第${i+1}行无效`)}});
 else{data=JSON.parse(text);if(!Array.isArray(data))data=data.records??data.rows??data.data;}
 if(!Array.isArray(data)||!data.length)throw Error('需要非空记录数组，或CSV/JSONL记录');if(data.some(x=>!x||typeof x!=='object'||Array.isArray(x)))throw Error('每条记录必须为字段对象');return data;
}
export function validateRows(rows,spec,{inference=false}={}){let errors=[],out=[];for(let i=0;i<rows.length;i++){let row={...rows[i]};for(const f of spec.features??[]){let v=row[f.name],blank=v===null||v===undefined||v==='';if(blank){if(f.required&&!f.nullable&&!(inference&&f.target))errors.push(`第${i+1}行：缺少${f.name}`);continue;}if(f.type==='number'||f.type==='integer'){let n=Number(v);if(!Number.isFinite(n)||(f.type==='integer'&&!Number.isInteger(n)))errors.push(`第${i+1}行：${f.name}需要${f.type==='integer'?'整数':'有限数值'}`);else row[f.name]=n;}else if(f.type==='date'){if(!/^\d{4}-\d{2}-\d{2}/.test(v)||!Number.isFinite(Date.parse(v)))errors.push(`第${i+1}行：${f.name}需要ISO日期`);}else if(f.type==='array'){if(typeof v==='string')try{row[f.name]=JSON.parse(v)}catch{}if(!Array.isArray(row[f.name]))errors.push(`第${i+1}行：${f.name}需要JSON数组`);}else if(typeof v!=='string')errors.push(`第${i+1}行：${f.name}需要文本`);}out.push(row);}return{valid:!errors.length,errors:errors.slice(0,12),totalErrors:errors.length,rows:out};}
function prng(seed){let a=Number(seed)>>>0;return()=>{a+=0x6D2B79F5;let t=Math.imul(a^a>>>15,1|a);t^=t+Math.imul(t^t>>>7,61|t);return((t^t>>>14)>>>0)/4294967296}}
function shuffle(a,seed){a=[...a];let r=prng(seed);for(let i=a.length-1;i>0;i--){let j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
export function splitData(rows,ratios=[70,15,15],strategy='random',seed=20261031,groupKey='well_id',dateKey='date'){
 if(ratios.length!==3||ratios.some(x=>!Number.isFinite(x)||x<=0)||Math.abs(ratios.reduce((a,b)=>a+b,0)-100)>1e-6)throw Error('三个比例必须大于0且合计100%');
 if(rows.length<3)throw Error('至少3条记录才能划分三组');let units;
 if(strategy==='coverage'){let shuffled=shuffle(rows,seed),need=new Set(shuffled.flatMap(r=>['e:'+r.head,'e:'+r.tail,'r:'+r.relation])),chosen=[],remaining=[...shuffled];if(rows.some(r=>!r.head||!r.tail||!r.relation))throw Error('实体覆盖划分需要head/relation/tail三元组');while(need.size){let best=-1,score=0;for(let i=0;i<remaining.length;i++){let r=remaining[i],n=['e:'+r.head,'e:'+r.tail,'r:'+r.relation].filter(k=>need.has(k)).length;if(n>score){score=n;best=i}}let r=remaining.splice(best,1)[0];chosen.push(r);for(let k of ['e:'+r.head,'e:'+r.tail,'r:'+r.relation])need.delete(k)}let n=rows.length,a=Math.max(1,Math.min(n-2,Math.floor(n*ratios[0]/100))),b=Math.max(a+1,Math.min(n-1,Math.floor(n*(ratios[0]+ratios[1])/100)));if(chosen.length>a)throw Error(`训练比例过低：覆盖全部实体和关系至少需要${chosen.length}条训练三元组，请提高训练比例`);let ordered=[...chosen,...remaining];return{train:ordered.slice(0,a),validation:ordered.slice(a,b),test:ordered.slice(b)};}
 if(strategy==='group'){let groups=new Map();for(const row of rows){if(row[groupKey]===null||row[groupKey]===undefined||row[groupKey]==='')throw Error('缺少分组字段 '+groupKey);let g=groups.get(row[groupKey])??[];g.push(row);groups.set(row[groupKey],g)}units=shuffle([...groups.values()],seed);if(units.length<3)throw Error('分组划分至少需要3个独立组');}
 else if(strategy==='time'){let groups=new Map();for(const row of rows){let d=Date.parse(row[dateKey]);if(!Number.isFinite(d))throw Error('时间划分要求有效日期 '+dateKey);let g=groups.get(d)??[];g.push(row);groups.set(d,g)}units=[...groups].sort((a,b)=>a[0]-b[0]).map(x=>x[1]);if(units.length<3)throw Error('时间划分至少需要3个不同日期');}
 else if(strategy==='random')units=shuffle(rows,seed).map(r=>[r]);else throw Error('未知划分策略');
 let n=units.length,a=Math.max(1,Math.min(n-2,Math.floor(n*ratios[0]/100))),b=Math.max(a+1,Math.min(n-1,Math.floor(n*(ratios[0]+ratios[1])/100)));
 return {train:units.slice(0,a).flat(),validation:units.slice(a,b).flat(),test:units.slice(b).flat()};
}
export function csv(rows){if(!rows?.length)return '';const keys=[...new Set(rows.flatMap(Object.keys))];const quote=v=>'"'+String(v===null||v===undefined?'':typeof v==='object'?JSON.stringify(v):v).replaceAll('"','""')+'"';return [keys,...rows.map(r=>keys.map(k=>r[k]))].map(r=>r.map(quote).join(',')).join('\n');}
export function overlapReport(splits,groupKey='well_id'){let seen=new Map(),groups=new Map(),identical=0,sharedGroups=new Set();for(const [sp,rows]of Object.entries(splits)){if(!['train','validation','test'].includes(sp))continue;for(const row of rows??[]){let k=JSON.stringify(Object.keys(row).sort().map(k=>[k,row[k]]));if(seen.has(k)&&seen.get(k)!==sp)identical++;else seen.set(k,sp);let g=row[groupKey];if(g!==undefined){if(groups.has(g)&&groups.get(g)!==sp)sharedGroups.add(g);else groups.set(g,sp)}}}return{identical,groups:sharedGroups.size};}
